package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.config.EntityHeatReportProofConfiguration;
import com.lianxibu.site.config.SourceAnalysisProofGraph;
import java.time.Clock;
import java.util.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.transaction.PlatformTransactionManager;

class EntityHeatReportProofConfigurationTest {
    static final List<String> FLAGS=CatalogDayReportProofConfigurationTest.FLAGS;
    ApplicationContextRunner base(){return new ApplicationContextRunner().withUserConfiguration(EntityHeatReportProofConfiguration.class);}
    ApplicationContextRunner enabled(){return base().withPropertyValues(FLAGS.stream().map(f->f+"=true").toArray(String[]::new));}
    @Test void DefaultFalseAndEachMissingFlagLeaveAllNativeConsumersAbsent(){base().run(c->{assertNull(c.getStartupFailure());assertFalse(c.containsBean("entityHeatCutoffProof"));assertFalse(c.containsBean("entityHeatSourceOrigin"));assertFalse(c.containsBean("entityHeatReportComponent"));});for(String missing:FLAGS){base().withPropertyValues(FLAGS.stream().filter(f->!f.equals(missing)).map(f->f+"=true").toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertFalse(c.containsBean("entityHeatCutoffProof"));assertFalse(c.containsBean("entityHeatSourceOrigin"));assertFalse(c.containsBean("entityHeatReportComponent"));});base().withPropertyValues(FLAGS.stream().map(f->f+"="+(!f.equals(missing))).toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertFalse(c.containsBean("entityHeatSourceOrigin"));assertFalse(c.containsBean("entityHeatReportComponent"));});}}
    @Test void FormalNativeConsumersRequireActualSourceGraphAndColdMandatoryPorts(){var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var clock=mock(Clock.class);var events=mock(EntityHeatEventProofService.class);var first=mock(EntityHeatEventAvailabilityService.class);var days=mock(NewsDayReportComponentService.class);var cohorts=mock(SourceDayCohortSealService.class);var graph=new SourceAnalysisProofGraph(source,tx,clock,()->{throw new AssertionError("cold proof configuration");});enabled().withBean(DataSource.class,()->source).withBean(PlatformTransactionManager.class,()->tx).withBean(EntityHeatEventProofService.class,()->events).withBean(EntityHeatEventAvailabilityService.class,()->first).withBean(NewsDayReportComponentService.class,()->days).withBean(SourceDayCohortSealService.class,()->cohorts).withBean(SourceAnalysisProofGraph.class,()->graph).run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(EntityHeatCutoffProofService.class).size());assertEquals(1,c.getBeansOfType(EntityHeatSourceOriginService.class).size());assertEquals(1,c.getBeansOfType(EntityHeatReportComponentService.class).size());assertSame(c.getBean("entityHeatReportComponent"),c.getBean(EntityHeatReportComponentService.class));assertSame(c.getBean("entityHeatCutoffProof"),c.getBean(EntityHeatCutoffProofService.class));assertSame(c.getBean("entityHeatSourceOrigin"),c.getBean(EntityHeatSourceOriginService.class));assertTrue(c.getBeansOfType(java.util.concurrent.ScheduledExecutorService.class).isEmpty());});verifyNoInteractions(source,tx,clock,events,first,days,cohorts);}
    @Test void EachMissingNativePortRejectsEnabledStartup(){for(int missing=0;missing<7;missing++){var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var graph=new SourceAnalysisProofGraph(source,tx,mock(Clock.class),()->true);var runner=enabled();if(missing!=0)runner=runner.withBean(DataSource.class,()->source);if(missing!=1)runner=runner.withBean(PlatformTransactionManager.class,()->tx);if(missing!=2)runner=runner.withBean(EntityHeatEventProofService.class,()->mock(EntityHeatEventProofService.class));if(missing!=3)runner=runner.withBean(EntityHeatEventAvailabilityService.class,()->mock(EntityHeatEventAvailabilityService.class));if(missing!=4)runner=runner.withBean(NewsDayReportComponentService.class,()->mock(NewsDayReportComponentService.class));if(missing!=5)runner=runner.withBean(SourceDayCohortSealService.class,()->mock(SourceDayCohortSealService.class));if(missing!=6)runner=runner.withBean(SourceAnalysisProofGraph.class,()->graph);runner.run(c->assertNotNull(c.getStartupFailure()));}}
}
